#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sum_sq_odds_basic() {
        assert_eq!(sum_sq_odds(&[1, 2, 3, -5]), 35);
        assert_eq!(sum_sq_odds(&[2, 4, 6]), 0);
        assert_eq!(sum_sq_odds(&[]), 0);
    }

    #[test]
    fn running_max_basic() {
        assert_eq!(running_max(&[3, 1, 4, 1, 5]), vec![3, 3, 4, 4, 5]);
        assert_eq!(running_max(&[-3, -5, -1]), vec![-3, -3, -1]);
    }

    #[test]
    fn running_max_empty() {
        assert_eq!(running_max(&[]), Vec::<i32>::new());
    }

    #[test]
    fn diffs() {
        assert_eq!(pairwise_diffs(&[1, 4, 9, 16]), vec![3, 5, 7]);
        assert_eq!(pairwise_diffs(&[5]), Vec::<i32>::new());
        assert_eq!(pairwise_diffs(&[]), Vec::<i32>::new());
        assert_eq!(pairwise_diffs(&[10, 3]), vec![-7]);
    }
}
